<template><section aria-label="科学计算器"><p class="tool-note">支持 + − * / ^、百分数 %、阶乘 !、括号、pi / e / ans，以及 sin、cos、tan、asin、acos、atan、sqrt、ln、log、exp、abs、round、floor、ceil、pow、min、max。乘法请显式输入 *，mod 表示取余，% 表示除以 100；ans 是上次成功结果（初值 0）；采用浮点运算，结果可能存在舍入误差。</p><div class="tool-actions"><label>角度<select v-model="angleMode" aria-label="计算器角度模式"><option value="DEG">DEG 角度</option><option value="RAD">RAD 弧度</option></select></label></div><label class="tool-label">数学表达式<input ref="expression" v-model="expression" aria-label="科学计算表达式" maxlength="500" autocomplete="off" spellcheck="false" placeholder="例如 sin(30) + sqrt(16)" @keyup.enter="calculate" /></label><div class="calculator-keys"><button v-for="key in keys" :key="key" type="button" @click="insert(key)">{{key}}</button></div><div class="tool-actions"><button type="button" @click="calculate">计算结果</button><button type="button" @click="expression=expression.slice(0,-1)">退格</button><button type="button" @click="expression='';answer=null;message=''">清空计算</button><button type="button" :disabled="answer===null" @click="copy">复制计算器结果</button></div><output v-if="answer!==null" class="unit-result" aria-live="polite">{{formatted}}</output><p v-if="message" class="tool-error" role="status">{{message}}</p><div v-if="history.length" class="calculator-history"><strong>本次页面记录</strong><button v-for="(item,index) in history" :key="index" type="button" @click="expression=item.expression">{{item.expression}} = {{item.formatted}}</button></div></section></template>
<script>
import {scientificCalculate} from '../../utils/scientific-calculator.mjs';
import {displayNumber} from '../../utils/utility-tools.mjs';
export default {name:'CalculatorTool',data:()=>({expression:'',angleMode:'DEG',answer:null,previous:0,message:'',history:[],keys:['7','8','9','/','sin(','4','5','6','*','cos(','1','2','3','-','sqrt(','0','.','(',')','+','pi','e','^','!','%']}),computed:{formatted(){return this.answer===null?'':displayNumber(this.answer);}},methods:{calculate(){try{const value=scientificCalculate(this.expression,this.angleMode,this.previous);this.answer=value;this.previous=value;this.message='';this.history.unshift({expression:this.expression,formatted:displayNumber(value)});this.history=this.history.slice(0,10);}catch(error){this.answer=null;this.message=error.message;}},async insert(key){const el=this.$refs.expression,start=el.selectionStart??this.expression.length,end=el.selectionEnd??start;this.expression=this.expression.slice(0,start)+key+this.expression.slice(end);await this.$nextTick();el.focus();el.setSelectionRange(start+key.length,start+key.length);},async copy(){try{await navigator.clipboard.writeText(String(this.answer));this.message='';}catch{this.message='复制未完成，请选择结果手动复制';}}}};
</script>
<style scoped>.calculator-keys{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:6px;max-width:500px;}.calculator-history{display:flex;flex-direction:column;align-items:flex-start;gap:8px;margin-top:16px;}.calculator-history button{text-align:left;overflow-wrap:anywhere;}</style>
